-- ===== from V084__lease_clause_template_required_default.sql =====
-- A required (non-optional) clause template must default to included; otherwise a contract
-- with no override would silently produce a lease missing a clause the template says must
-- always be present. See LeaseClauseResolver, which additionally forces included=true at read
-- time for any non-optional template, regardless of this default or a stored override.
ALTER TABLE lease_clause_templates
ADD CONSTRAINT chk_lease_clause_templates_required_default CHECK (
    optional
    OR default_included
);

-- ===== from V087__lease_clause_template_audit_columns.sql =====
-- lease_clause_templates is edited live by individual backoffice admins through ordinary CRUD
-- (unlike the rent_regulation_* reference tables, which are wholesale-replaced by a catalog
-- reload and deliberately carry no per-row audit trail), so who created/last touched a template
-- is real, useful information. The actor is a backoffice Keycloak subject id, not a row in the
-- app's own `users` table (a different realm), so these are plain UUID columns with no FK.
ALTER TABLE lease_clause_templates
ADD COLUMN created_by UUID,
ADD COLUMN updated_by UUID;

-- Existing rows predate this column and have no real actor to attribute to the backfill.
-- Matches Constants.SYSTEM_USER_ID, the same placeholder used for other system-attributed writes.
UPDATE lease_clause_templates
SET
    created_by = '00000000-0000-0000-0000-000000000001',
    updated_by = '00000000-0000-0000-0000-000000000001'
WHERE
    created_by IS NULL;

ALTER TABLE lease_clause_templates
ALTER COLUMN created_by
SET NOT NULL,
ALTER COLUMN updated_by
SET NOT NULL;

-- ===== from V090__lease_clause_template_active_uniqueness.sql =====
-- uq_lease_clause_templates_country_key_version allows two different versions of the same
-- (country_code, clause_key) to both be active (deleted_at IS NULL) at once — nothing enforces
-- supersede-on-save. Not exploited today, but a partial unique index closes the gap so a future
-- bug (e.g. a new version inserted without soft-deleting the old one) fails loudly at the
-- database instead of silently resolving two active templates for the same clause.
CREATE UNIQUE INDEX uq_lease_clause_templates_active_country_key ON lease_clause_templates (country_code, clause_key)
WHERE
    deleted_at IS NULL;

-- ===== from V091__lease_kind_and_regime.sql =====
ALTER TABLE lease_clause_templates
ADD COLUMN lease_kind VARCHAR(32) NOT NULL DEFAULT 'RESIDENTIAL',
ADD COLUMN pinned BOOLEAN NOT NULL DEFAULT FALSE;

-- Existing V083 rows are placeholder text: keep them as the fallback for every country/kind
-- that has no real document yet.
UPDATE lease_clause_templates
SET
    lease_kind = 'LEGACY';

ALTER TABLE lease_clause_templates
ADD CONSTRAINT chk_lease_clause_templates_kind CHECK (
    lease_kind IN (
        'LEGACY',
        'RESIDENTIAL',
        'RESIDENTIAL_FURNISHED',
        'COMMERCIAL',
        'MIXED_USE',
        'AGRICULTURAL',
        'SHORT_TERM',
        'STUDENT_MOBILITY'
    )
);

ALTER TABLE lease_clause_templates
DROP CONSTRAINT uq_lease_clause_templates_country_key_version;

ALTER TABLE lease_clause_templates
ADD CONSTRAINT uq_lease_clause_templates_country_kind_key_version UNIQUE (country_code, lease_kind, clause_key, version);

-- V090's partial index must also become kind-aware, otherwise the same clause_key could not be
-- active under two different kinds of one country.
DROP INDEX uq_lease_clause_templates_active_country_key;

CREATE UNIQUE INDEX uq_lease_clause_templates_active_country_kind_key ON lease_clause_templates (country_code, lease_kind, clause_key)
WHERE
    deleted_at IS NULL;

ALTER TABLE contracts
ADD COLUMN lease_regime VARCHAR(32) NOT NULL DEFAULT 'STANDARD',
ADD CONSTRAINT chk_contracts_lease_regime CHECK (
    lease_regime IN ('STANDARD', 'SHORT_TERM', 'STUDENT_OR_MOBILITY')
);

-- ===== from V092__seed_nl_residential_lease_clauses.sql =====
