-- ===== from V095__seed_es_lease_clauses.sql =====
-- ES residential (arrendamiento de vivienda, Ley 29/1994 de Arrendamientos Urbanos, titulo II) and commercial
-- (arrendamiento para uso distinto del de vivienda, LAU titulo III) clause structure. The legal text of each clause
-- lives in templates/documents/lease-agreement/ES/{residential,commercial}/{lang}.html (fragment clause-<clause_key>);
-- these rows carry only structure (required/pinned/order) and the i18n keys of the title and one-line summary
-- shown in the clause toggle UI. Draft content, NOT vetted by legal counsel. The V083 ES placeholder rows
-- (lease_kind LEGACY) stay as the fallback for the other kinds. Pinned clauses (parties, premises) sort before
-- every movable clause. Required clauses (optional = FALSE) must default to included
-- (chk_lease_clause_templates_required_default). The deposit (fianza) is required in both kinds: art. 36.1 LAU makes
-- it compulsory.
INSERT INTO
