-- ===== from V096__seed_pt_lease_clauses.sql =====
-- PT residential (arrendamento urbano para habitacao, Codigo Civil art. 1064 ff. and 1092-1107, NRAU Lei 6/2006) and
-- commercial (arrendamento urbano para fins nao habitacionais, Codigo Civil art. 1108-1113) clause structure. The legal
-- text of each clause lives in templates/documents/lease-agreement/PT/{residential,commercial}/{lang}.html (fragment
-- clause-<clause_key>); these rows carry only structure (required/pinned/order) and the i18n keys of the title and
-- one-line summary shown in the clause toggle UI. Draft content, NOT vetted by legal counsel. The V083 PT placeholder
-- rows (lease_kind LEGACY) stay as the fallback for the other kinds. Pinned clauses (parties, premises) sort before
-- every movable clause. Required clauses (optional = FALSE) must default to included
-- (chk_lease_clause_templates_required_default). The deposit (caucao) is optional in both kinds: Codigo Civil art. 1076
-- allows it (up to 2 rendas) but does not require it.
