    lease_clause_templates (
        id,
        identifier,
        country_code,
        lease_kind,
        clause_key,
        title_i18n_key,
        body_i18n_key,
        default_included,
        optional,
        pinned,
        sort_order,
        version,
        created_by,
        updated_by
    )
