-- ===== from V097__seed_be_lease_clauses.sql =====
-- BE residential (bail de residence principale / huurovereenkomst voor een hoofdverblijfplaats: regional law since the
-- sixth state reform - Vlaams Woninghuurdecreet of 9 November 2018, decret wallon du 15 mars 2018 relatif au bail
-- d'habitation, Code bruxellois du Logement title XI; the documents branch on regionCode VLG / WAL / BRU) and
