-- movable clause. Required clauses (optional = FALSE) must default to included
-- (chk_lease_clause_templates_required_default). The rental guarantee is optional in both kinds (permitted, not
-- required, by the regional decrees); the energy certificate and the annexes are required in the residential lease
-- (Walloon art. 3, section 1, 12 and section 2; Brussels art. 217 and 218, section 5; Flemish art. 8 and 10).
