-- AT residential (Mietvertrag über eine Wohnung) and commercial (Mietvertrag über eine Geschäftsräumlichkeit)
-- clause structure. The legal text of each clause lives in
-- templates/documents/lease-agreement/AT/{residential,commercial}/{lang}.html (fragment clause-<clause_key>);
-- these rows carry only structure (required/pinned/order) and the i18n keys of the title and one-line summary
-- shown in the clause toggle UI. Draft content, NOT vetted by legal counsel. Pinned clauses (parties, premises)
