-- DK residential (lov om leje, lov nr. 341 af 22/03/2022 as amended) and commercial (lov om leje af erhvervslokaler
-- m.v., LBK nr 1446 af 09/11/2022) clause structure. The legal text of each clause lives in
-- templates/documents/lease-agreement/DK/{residential,commercial}/{lang}.html (fragment clause-<clause_key>); these
-- rows carry only structure (required/pinned/order) and the i18n keys of the title and one-line summary shown in the
-- clause toggle UI. Draft content, NOT vetted by legal counsel. V083 seeded no DK placeholder rows (lease_kind
-- LEGACY), so these are the first DK clause rows. Pinned clauses (parties, premises) sort before every movable clause.
-- Required clauses (optional = FALSE) must default to included (chk_lease_clause_templates_required_default). The
-- deposit is optional in both kinds: lov om leje § 59 allows it (up to 3 months' rent) but does not require it, and
-- erhvervslejeloven sets no cap on it (it addresses deposits only in § 6, stk. 1, and § 38, stk. 3).
