-- ===== from V102__seed_gr_lease_clauses.sql =====
-- GR residential (misthosi katoikias: Astikos Kodikas art. 574-618, Law 1703/1987 art. 2 par. 1) and commercial
-- (misthosi epaggelmatikis stegis: Astikos Kodikas, P.D. 34/1995 as limited by Law 4242/2014 art. 13) clause
-- structure. The legal text of each clause lives in templates/documents/lease-agreement/GR/{residential,commercial}/
-- {lang}.html (fragment clause-<clause_key>); these rows carry only structure (required/pinned/order) and the i18n
-- keys of the title and one-line summary shown in the clause toggle UI. Draft content, NOT vetted by legal counsel.
-- Pinned clauses (parties, premises) sort before every movable clause. Required clauses (optional = FALSE) must
-- default to included (chk_lease_clause_templates_required_default). The deposit (eggyisi) is optional in both
-- kinds: no statutory provision relied on requires one.
