-- ===== from V103__seed_ie_lease_clauses.sql =====
-- IE residential (Residential Tenancies Act 2004 as amended, in particular by the Residential Tenancies
-- (Miscellaneous Provisions) Act 2026: Part 4 tenancies, tenancies of minimum duration, national rent limits) and
-- commercial (business lettings: Landlord and Tenant (Amendment) Act 1980, Land and Conveyancing Law Reform Act 2009
-- s.132) clause structure. The legal text of each clause lives in
-- templates/documents/lease-agreement/IE/{residential,commercial}/en.html (fragment clause-<clause_key>; English is
-- the only language of the documents); these rows carry only structure (required/pinned/order) and the i18n keys of
-- the title and one-line summary shown in the clause toggle UI. Draft content, NOT vetted by legal counsel. V083
-- seeded no IE placeholder rows (lease_kind LEGACY), so none are touched. Pinned clauses (parties, premises) sort
-- before every movable clause. Required clauses (optional = FALSE) must default to included
-- (chk_lease_clause_templates_required_default). The residential deposit is optional: the Act caps it at 1 month's
-- rent (s.19B) but does not require it. The commercial renewal clause is required: it records whether the tenant
-- has renounced the statutory entitlement to a new tenancy (1980 Act s.17(1)(a)(iiia)).
INSERT INTO
    lease_clause_templates (
        id,
        identifier,
        country_code,
        lease_kind,
        clause_key,
        title_i18n_key,
        body_i18n_key,
        default_included,
        optional,
        pinned,
        sort_order,
        version,
        created_by,
        updated_by
    )
