-- ===== from V105__seed_lu_lease_clauses.sql =====
-- LU residential (bail a usage d'habitation, loi modifiee du 21 septembre 2006 as amended by the loi du 23 juillet
-- 2024) and commercial (bail commercial, Code civil art. 1762-3 to 1762-13 as enacted by the loi du 3 fevrier 2018)
-- clause structure. The legal text of each clause lives in
-- templates/documents/lease-agreement/LU/{residential,commercial}/{fr,de,en}.html (fragment clause-<clause_key>; fr
-- authoritative); these rows carry only structure (required/pinned/order) and the i18n keys of the title and one-line
-- summary shown in the clause toggle UI. Draft content, NOT vetted by legal counsel. No earlier migration seeds LU
-- clause rows (no lease_kind LEGACY placeholder rows for LU). Pinned clauses (parties, premises) sort before
-- every movable clause. Required clauses (optional = FALSE) must default to included
-- (chk_lease_clause_templates_required_default). Residential service-costs is required because the amount of the
-- advance payments or flat rate for charges is mandatory content of the written lease (art. 5, paragraphe 1, 5deg);
-- the deposit (garantie locative) is optional in both kinds: the law allows it but does not require it.
