-- ===== from V106__seed_no_lease_clauses.sql =====
-- NO residential (husleieloven, lov 26. mars 1999 nr. 17, leie av bolig) and commercial (husleieloven for lokale,
-- largely derogable by agreement under § 1-2 second paragraph) clause structure. The legal text of each clause lives in
-- templates/documents/lease-agreement/NO/{residential,commercial}/{lang}.html (fragment clause-<clause_key>); these
-- rows carry only structure (required/pinned/order) and the i18n keys of the title and one-line summary shown in the
-- clause toggle UI. Draft content, NOT vetted by legal counsel. V083 has no NO rows, so these are the first NO clause
-- rows (other kinds keep the generic fallback). Pinned clauses (parties, premises) sort before every movable clause.
-- Required clauses (optional = FALSE) must default to included (chk_lease_clause_templates_required_default). The
-- deposit (depositum, § 3-5) is optional in both kinds: the Act allows it (for dwellings up to the sum of 6 months'
-- rent) but does not require it. The energy certificate clause is optional because energimerkeforskriften § 6 and
-- § 9 exempt some lettings.
INSERT INTO
    lease_clause_templates (
        id,
        identifier,
        country_code,
        lease_kind,
        clause_key,
        title_i18n_key,
        body_i18n_key,
        default_included,
        optional,
        pinned,
        sort_order,
        version,
        created_by,
        updated_by
    )
