-- ===== from V107__seed_pl_lease_clauses.sql =====
-- PL residential (najem lokalu mieszkalnego: Kodeks cywilny art. 659-692 and the ustawa z dnia 21 czerwca 2001 r. o
-- ochronie praw lokatorow, mieszkaniowym zasobie gminy i o zmianie Kodeksu cywilnego) and commercial (najem lokalu
-- uzytkowego: Kodeks cywilny art. 659-688^2) clause structure. The legal text of each clause lives in
-- templates/documents/lease-agreement/PL/{residential,commercial}/{lang}.html (fragment clause-<clause_key>); these
-- rows carry only structure (required/pinned/order) and the i18n keys of the title and one-line summary shown in the
-- clause toggle UI. Draft content, NOT vetted by legal counsel. The residential document covers the ordinary lease
-- only, not the najem okazjonalny or najem instytucjonalny. V083 seeded no PL LEGACY rows.
-- Pinned clauses (parties, premises) sort before every movable clause. Required clauses (optional = FALSE) must
-- default to included (chk_lease_clause_templates_required_default). The deposit (kaucja) is optional in both kinds:
-- art. 6 ust. 1 u.o.p.l. allows it (up to 12 times the monthly rent) but does not require it.
INSERT INTO
    lease_clause_templates (
        id,
        identifier,
        country_code,
        lease_kind,
        clause_key,
        title_i18n_key,
        body_i18n_key,
        default_included,
        optional,
        pinned,
        sort_order,
        version,
        created_by,
        updated_by
    )
