-- ===== from V110__seed_ch_lease_clauses.sql =====
-- CH residential (Miete von Wohnraeumen) and commercial (Miete von Geschaeftsraeumen) clause structure under the
-- Swiss Code of Obligations (OR art. 253-273c) and the VMWG (SR 221.213.11). The legal text of each clause lives in
-- templates/documents/lease-agreement/CH/{residential,commercial}/{de,fr,it,en}.html (fragment clause-<clause_key>;
-- de is authoritative); these rows carry only structure (required/pinned/order) and the i18n keys of the title and
-- one-line summary shown in the clause toggle UI. Draft content, NOT vetted by legal counsel. No earlier CH clause
-- rows exist. Pinned clauses (parties, premises) sort before every movable clause. Required clauses (optional =
-- FALSE) must default to included (chk_lease_clause_templates_required_default). The deposit (Sicherheit, OR art.
-- 257e) is optional in both kinds: the law caps it for residential premises but does not require it.
INSERT INTO
    lease_clause_templates (
