-- ===== from V111__seed_ca_lease_clauses.sql =====
-- CA residential and commercial clause structure. Canadian tenancy law is provincial and territorial: the documents
-- branch on the contract region for Ontario (Residential Tenancies Act, 2006 / Commercial Tenancies Act), Quebec
-- (Civil Code of Quebec arts. 1851-2000) and British Columbia (Residential Tenancy Act / Commercial Tenancy Act) and
-- print a general text for the other provinces and territories. The legal text of each clause lives in
-- templates/documents/lease-agreement/CA/{residential,commercial}/{en,fr}.html (fragment clause-<clause_key>; en is
-- authoritative, fr machine-drafted); these rows carry only structure (required/pinned/order) and the i18n keys of the
-- title and one-line summary shown in the clause toggle UI. Draft content, NOT vetted by legal counsel. The residential
-- document is not the Ontario Standard Form of Lease nor the mandatory lease form of the Tribunal administratif du
-- logement and says so where those forms apply. No CA LEGACY rows exist; the other kinds keep using the generic
-- placeholder lease. Pinned clauses (parties, premises) sort before every movable clause. Required clauses
-- (optional = FALSE) must default to included (chk_lease_clause_templates_required_default). The deposit is optional:
-- Quebec prohibits it for dwellings (art. 1904 C.C.Q.) and Ontario allows only a rent deposit (RTA s. 106).
INSERT INTO
    lease_clause_templates (
        id,
        identifier,
        country_code,
        lease_kind,
        clause_key,
        title_i18n_key,
        body_i18n_key,
        default_included,
        optional,
        pinned,
        sort_order,
        version,
        created_by,
        updated_by
    )
