-- ===== from V112__seed_us_lease_clauses.sql =====
-- US residential and commercial lease clause structure. United States landlord-tenant law is state and local law;
-- the documents branch on the state (first 2 letters of contracts.region_code) for CA, DC, MA, MD, ME, MN, NJ, NY,
-- OR and WA and print a general text for any other state; federal rules (lead-based paint disclosure 42 U.S.C.
-- 4852d, Fair Housing Act, SCRA, ADA Title III) apply everywhere. The legal text of each clause lives in
-- templates/documents/lease-agreement/US/{residential,commercial}/en.html (fragment clause-<clause_key>, English
-- only); these rows carry only structure (required/pinned/order) and the i18n keys of the title and one-line
-- summary shown in the clause toggle UI. Draft content, NOT vetted by legal counsel. V083 has no US placeholder
-- rows. Pinned clauses (parties, premises) sort before every movable clause. Required clauses (optional = FALSE)
-- must default to included (chk_lease_clause_templates_required_default). The residential lead-based paint and
-- state disclosures clause is required; the deposit is optional (no federal requirement).
INSERT INTO
    lease_clause_templates (
