-- ===== from V113__seed_nl_commercial_lease_clauses.sql =====
-- NL commercial (huur van bedrijfsruimte) clause structure. The legal text of each clause lives in
-- templates/documents/lease-agreement/NL/commercial/{nl,en}.html (fragment clause-<clause_key>);
-- these rows carry only structure (required/pinned/order) and the i18n keys of the title and
-- one-line summary shown in the clause toggle UI. Draft content, NOT vetted by legal counsel.
-- The documents state each regime-specific rule conditionally (art. 7:290 BW bedrijfsruimte vs
-- other business premises, art. 7:230a BW); the parties tick the regime in the premises clause.
-- Pinned clauses (parties, premises) sort before every movable clause. Required clauses
-- (optional = FALSE) must default to included (chk_lease_clause_templates_required_default).
INSERT INTO
    lease_clause_templates (
        id,
        identifier,
        country_code,
        lease_kind,
        clause_key,
        title_i18n_key,
        body_i18n_key,
        default_included,
        optional,
        pinned,
        sort_order,
        version,
        created_by,
        updated_by
    )
